"""matplotlib.backends.registry — backend-name registry. Tracks which
backend names matplotlib knows about and resolves them to module
paths the importer can use.
"""

from enum import Enum


class BackendFilter(Enum):
    """Filter the backend list by capability — interactive vs.
    file-only. Real Enum so ``isinstance(filter, BackendFilter)`` works."""

    INTERACTIVE = 'interactive'
    NON_INTERACTIVE = 'non_interactive'


# Canonical interactive backends (those that pop a GUI window).
_INTERACTIVE = {
    'qtagg', 'qt5agg', 'qt4agg', 'qtcairo', 'qt5cairo',
    'gtk3agg', 'gtk3cairo', 'gtk4agg', 'gtk4cairo',
    'wxagg', 'wx', 'wxcairo',
    'tkagg', 'tkcairo',
    'macosx', 'webagg', 'nbagg',
}

# File-output / non-interactive backends.
_NON_INTERACTIVE = {
    'agg', 'pdf', 'ps', 'svg', 'pgf', 'cairo',
    'template', 'mixed',
}


class BackendRegistry:
    """Registry mapping backend names to their module paths."""

    def __init__(self):
        self._registered = {}

    def register(self, name, module):
        """Add a third-party backend to the registry."""
        self._registered[str(name).lower()] = str(module)

    def list_builtin(self, filter=None):
        """Return the list of built-in backend names, optionally
        filtered by interactive/non-interactive."""
        if filter is None:
            return sorted(_INTERACTIVE | _NON_INTERACTIVE)
        # Accept either the Enum value or the bare string.
        f_val = filter.value if isinstance(filter, BackendFilter) else filter
        if f_val == BackendFilter.INTERACTIVE.value:
            return sorted(_INTERACTIVE)
        if f_val == BackendFilter.NON_INTERACTIVE.value:
            return sorted(_NON_INTERACTIVE)
        raise ValueError(f'unknown BackendFilter: {filter!r}')

    def is_valid_backend(self, name):
        """True iff ``name`` is one we can resolve (built-in or
        third-party registered)."""
        n = str(name).lower()
        return (n in _INTERACTIVE or n in _NON_INTERACTIVE
                or n in self._registered
                or n.startswith('module://'))

    def resolve_backend(self, backend):
        """Map a backend name to the importable module path."""
        if backend in self._registered:
            return self._registered[backend]
        if isinstance(backend, str) and backend.startswith('module://'):
            return backend[len('module://'):]
        return f'matplotlib.backends.backend_{str(backend).lower()}'

    def resolve_gui_or_backend(self, gui_or_backend):
        """Variant of ``resolve_backend`` that also accepts shorthand
        GUI names (qt, gtk, wx, tk, …). Mirrors upstream's helper."""
        gui = str(gui_or_backend).lower()
        gui_to_backend = {
            'qt': 'qtagg', 'qt5': 'qt5agg', 'qt6': 'qtagg',
            'gtk': 'gtk3agg', 'gtk3': 'gtk3agg', 'gtk4': 'gtk4agg',
            'wx': 'wxagg', 'tk': 'tkagg', 'osx': 'macosx',
            'web': 'webagg', 'nb': 'nbagg',
        }
        return self.resolve_backend(gui_to_backend.get(gui, gui))


backend_registry = BackendRegistry()
